/* FM1 Tape OS: internal types shared by the modules of the unity build (src/tapeos.c). */
#pragma once
#include <stdint.h>
#include "../tapeos.h"
#undef FS                        /* the FM1 build: Dinghy's platform.c defines FS 44100u */
#include "felucca_types.h"       /* third_party/felucca: the ANALOG engine's types (verbatim excerpt) */
#include "felucca_tables.h"      /* generated by third_party/felucca/gen_tables.py: FS, CTL, SINE, pitch_inc .. */

#if FS != 44100 || CTL != 32
#error "FM1 Tape OS expects FS 44100 and CTL 32 (felucca_tables.h)"
#endif

/* big buffers: the FM1's 336 KB pool (Dinghy app.ld .pool), plain statics elsewhere */
#ifndef TOS_POOL
#define TOS_POOL
#endif

#define NTRACK 4u                /* tape tracks = mixer channels */
#define NSVOICE 8u               /* synth voices (shared by live play and the tape) */
#define NDRUM 8u                 /* drum sounds, one voice each (a new hit restarts it) */
#define TICK_SAMPLES CTL         /* the tape clock: one tick per control block (32 samples, 0.726 ms) */

enum { MODE_SYNTH, MODE_DRUM, MODE_TAPE, MODE_MIXER, NMODE };
enum { PAGE_MAIN, PAGE_ENV, PAGE_LFO, PAGE_FX, NPAGE };

/* ---- a synth sound: the ANALOG engine's parameters (in Felucca's track_t.p[]) + envelope + LFO */
enum { LFO_TRI, LFO_SINE, LFO_SQR, LFO_SH, NLFOWAVE };
enum { LDEST_CUT, LDEST_PITCH, LDEST_AMP, LDEST_SHAPE, NLDEST };
typedef struct {
    track_t t;                   /* t.p[P_E0..P_E7]: WAVE DTN MIX NOIS CUT RES DRV KTR; t.p[P_FTYPE] */
    uint8_t env[4];              /* ATK DEC SUS REL, 0..127 */
    int8_t fenv;                 /* envelope -> cutoff, -64..63 */
    uint8_t lrate, ldepth, ldest, lwave;
    uint8_t preset;              /* the ANALOG preset it started from */
} sound_t;

/* ---- drum sounds */
typedef struct { uint8_t tune, decay, tone, level; } dsound_t;

/* ---- the parameter registry: everything a knob can change, by id */
enum {
    PR_WAVE, PR_DTN, PR_MIX, PR_NOIS, PR_CUT, PR_RES, PR_DRV, PR_KTR, PR_FTYPE,
    PR_ATK, PR_DEC, PR_SUS, PR_REL, PR_FENV,
    PR_LRATE, PR_LDEPTH, PR_LDEST, PR_LWAVE,
    PR_PRESET,
    PR_DRSEL, PR_DTUNE, PR_DDECAY, PR_DTONE, PR_DLEVEL,
    PR_TRACK, PR_BARS, PR_BPM, PR_LOOP,
    PR_VOL1, PR_VOL2, PR_VOL3, PR_VOL4,
    PR_PAN1, PR_PAN2, PR_PAN3, PR_PAN4,
    PR_MUTE1, PR_MUTE2, PR_MUTE3, PR_MUTE4,
    PR_MASTER,
    PR_FXTIME, PR_FXFDBK, PR_FXMIX, PR_FXTONE,
    NPARAM
};
typedef struct {
    const char *name;
    int16_t min, max;
    const char *const *names;    /* enumerated values, 0 = a number */
} pdesc_t;

/* ---- commands: main loop -> audio side (a single-producer single-consumer ring) */
enum {
    CMD_NOTE_ON, CMD_NOTE_OFF,           /* a: note, b: velocity */
    CMD_DRUM_ON, CMD_DRUM_OFF,           /* a: drum sound */
    CMD_PARAM,                           /* a: PR_*, b: delta */
    CMD_PLAY, CMD_REC, CMD_REWIND, CMD_SEEK,   /* CMD_SEEK b: beats (+/-) */
    CMD_UNDO, CMD_REDO, CMD_ERASE_TRACK,
    CMD_PANIC
};
typedef struct { uint8_t type, a; int16_t b; } cmd_t;

/* ---- the tape: four tracks of note events (EventTape, not audio: see docs/ARCHITECTURE.md) */
#define TAPE_MAXEV 1024u         /* events per track */
#define TEV_DRUM 0x80u           /* in tev_t.vel: a drum hit (note = drum sound) */
typedef struct {
    uint32_t tick;               /* start, in ticks from the tape's beginning */
    uint16_t dur;                /* ticks (at least 1) */
    uint8_t note, vel;           /* vel bit 7: TEV_DRUM */
    uint16_t add, del;           /* history: the operation that added / deleted it (0 = never deleted) */
} tev_t;
_Static_assert(sizeof(tev_t) == 12, "tev_t: 12 bytes");

#define HIST_LEVELS 7u           /* undo levels (as #248's tape undo: up to 7 recordings back) */
enum { OP_NONE, OP_TAKE, OP_ERASE };
typedef struct { uint8_t type, track; uint16_t nev; } hop_t;

/* ---- the state the screen reads (written by the audio side; plain values, read as they are) */
typedef struct {
    uint8_t active;              /* sounding (any stage) */
    uint8_t note, track, src;
    int32_t level;               /* envelope, Q15 */
} vview_t;
